import React, { useEffect, useRef, useState } from "react";
import { socket } from "../api/socket";

export default function ChatWidget({ name, role }) {
  const [isOpen, setIsOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("chat"); // "chat" | "participants"
  const [messages, setMessages] = useState([]);
  const [participants, setParticipants] = useState([]);
  const [input, setInput] = useState("");
  const listRef = useRef(null);

  const currentName = name || (role === "teacher" ? "Teacher" : "Guest");

  useEffect(() => {
    const handleHistory = ({ messages }) => setMessages(messages || []);
    const handleMessage = (msg) =>
      setMessages((prev) => [...prev, msg]);
    const handleStudents = ({ students }) =>
      setParticipants(students || []);

    socket.on("chat:history", handleHistory);
    socket.on("chat:message", handleMessage);
    socket.on("students:update", handleStudents);

    socket.emit("chat:getHistory");

    return () => {
      socket.off("chat:history", handleHistory);
      socket.off("chat:message", handleMessage);
      socket.off("students:update", handleStudents);
    };
  }, []);

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  const sendMessage = (e) => {
    e.preventDefault();
    const text = input.trim();
    if (!text) return;
    socket.emit("chat:message", {
      sender: currentName,
      role,
      text,
    });
    setInput("");
  };

  const isOwn = (msg) => msg.sender === currentName;

  return (
    <>
      <button
        type="button"
        className="chat-fab"
        onClick={() => setIsOpen((o) => !o)}
      >
        💬
      </button>

      {isOpen && (
        <div className="chat-panel">
          <div className="chat-tabs">
            <button
              type="button"
              className={
                "chat-tab-btn" +
                (activeTab === "chat" ? " chat-tab-btn--active" : "")
              }
              onClick={() => setActiveTab("chat")}
            >
              Chat
            </button>
            <button
              type="button"
              className={
                "chat-tab-btn" +
                (activeTab === "participants" ? " chat-tab-btn--active" : "")
              }
              onClick={() => setActiveTab("participants")}
            >
              Participants
            </button>
          </div>

          {activeTab === "chat" ? (
            <>
              <div className="chat-messages" ref={listRef}>
                {messages.length === 0 && (
                  <div className="chat-empty">No messages yet. Say hi 👋</div>
                )}
                {messages.map((msg) => (
                  <div
                    key={msg.id}
                    className={
                      "chat-message-row" +
                      (isOwn(msg) ? " chat-message-row--own" : "")
                    }
                  >
                    <div className="chat-message-sender">
                      {msg.sender}
                    </div>
                    <div className="chat-message-bubble">
                      {msg.text}
                    </div>
                  </div>
                ))}
              </div>
              <form className="chat-input-row" onSubmit={sendMessage}>
                <input
                  className="chat-input"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Type a message"
                />
                <button type="submit" className="chat-send-btn">
                  Send
                </button>
              </form>
            </>
          ) : (
            <div className="chat-participants">
              {participants.length === 0 && (
                <div className="chat-empty">No participants yet.</div>
              )}
              {participants.map((p, idx) => (
                <div key={idx} className="chat-participant">
                  {p.name}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </>
  );
}
